package com.inventra.backend.service; import com.inventra.backend.dto.*; import com.inventra.backend.model.*; import com.inventra.backend.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class AlertService {private final InventoryAlertRepository repo;private final ProductRepository products;private final InventoryRepository inv;public AlertService(InventoryAlertRepository r,ProductRepository p,InventoryRepository i){repo=r;products=p;inv=i;}public List<AlertResponse> all(){return repo.findByAcknowledgedFalseOrderByCreatedAtDesc().stream().map(this::map).toList();}public void refresh(){for(Product p:products.findAll()){if(p.getStockQuantity()<=p.getReorderLevel()){InventoryAlert a=new InventoryAlert();a.setProductId(p.getId());a.setType(p.getStockQuantity()==0?AlertType.OUT_OF_STOCK:AlertType.LOW_STOCK);a.setSeverity(p.getStockQuantity()==0?"CRITICAL":"WARNING");a.setMessage(p.getName()+" is below its reorder level.");repo.save(a);}}}public AlertResponse acknowledge(String id){InventoryAlert a=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Alert not found"));a.setAcknowledged(true);return map(repo.save(a));}private AlertResponse map(InventoryAlert a){return new AlertResponse(a.getId(),a.getProductId(),a.getWarehouseId(),a.getType(),a.getSeverity(),a.getMessage(),a.isAcknowledged(),a.getCreatedAt());}}
